<?php declare(strict_types=1);require_once dirname(__DIR__).'/includes/functions.php';$u=requireRole('member');if(!post()){redirect('profile.php');}verifyCsrf();$event=(int)($_POST['event_id']??0);$date=clean('participation_date',20);$details=clean('details',3000);$s=db()->prepare('SELECT id,event_date FROM events WHERE id=? AND event_date<=CURDATE()');$s->execute([$event]);$ev=$s->fetch();if(!$ev){flash('error','Please choose a valid past event.');redirect('profile.php');}if(!$date||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$date>$ev['event_date']){flash('error','The participation date must be valid and cannot be after the event date.');redirect('profile.php');}try{db()->prepare('INSERT INTO participation_claims(member_id,event_id,participation_date,details) VALUES(?,?,?,?)')->execute([$u['id'],$event,$date,$details]);flash('success','Participation claim submitted for admin verification.');}catch(PDOException $e){flash('error','A claim for this event already exists.');}redirect('profile.php');
